<?php require 'app.php';need_school();$_GET['class_id']=0;$id=(int)($_GET['id']??0);$args=[school_id(),$id];$sql='SELECT st.*,c.name class_name,c.stream,s.name school_name,s.logo_url FROM students st JOIN schools s ON s.id=st.school_id LEFT JOIN classes c ON c.id=st.class_id WHERE st.school_id=? AND st.id=?';if(in_array(role(),['patron','matron'],true)){$ids=assigned_class_ids();$sql.=' AND st.class_id IN ('.($ids?implode(',',array_fill(0,count($ids),'?')):'NULL').')';$args=array_merge($args,$ids);}$q=db()->prepare($sql);$q->execute($args);$r=$q->fetch();if(!$r){http_response_code(404);exit('Student not found or not assigned to you.');}$q=db()->prepare('SELECT qr_token FROM id_cards WHERE student_id=?');$q->execute([$id]);$token=$q->fetchColumn();if(!$token){$token=bin2hex(random_bytes(32));db()->prepare('INSERT INTO id_cards(school_id,student_id,qr_token) VALUES(?,?,?)')->execute([school_id(),$id,$token]);}ob_start();?><div class="panel"><button onclick="window.print()">Print this card</button><div class="idcard" style="max-width:390px;margin:20px auto"><div class="cardhead"><?php if($r['logo_url']):?><img src="<?=h($r['logo_url'])?>" style="width:34px;height:34px;object-fit:contain;vertical-align:middle;margin-right:8px"><?php endif;?><?=h($r['school_name'])?></div><div class="cardbody"><?php if($r['photo_url']):?><img src="<?=h($r['photo_url'])?>"><?php endif;?><div><h3><?=h($r['first_name'].' '.$r['last_name'])?></h3><p>Admission: <?=h($r['admission_number'])?></p><p>Class: <?=h(($r['class_name']??'').' '.($r['stream']??''))?></p></div></div><div class="qr"><img style="width:90px;height:90px" alt="QR verification" src="https://api.qrserver.com/v1/create-qr-code/?size=140x140&amp;data=<?=rawurlencode(((!empty($_SERVER['HTTPS'])?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').dirname($_SERVER['SCRIPT_NAME']).'/verify.php?token='.$token))?>"></div></div></div><style>@media print{.top,.nav,button,h1{display:none!important}}</style><?php page('Student ID Card',ob_get_clean());
